@router.put("/canvas/whiteboards/{board_pk}")
async def update_whiteboard_state(
    board_pk: str,
    payload: WhiteboardUpdatePayload,
    current_user: User = Depends(get_current_user)
):
    try:
        board = WhiteboardSession.get(board_pk)
    except NotFoundError:
        raise HTTPException(status_code=404, detail="Whiteboard session not found")

    if board.workspace_id != current_user.workspace_id:
        raise HTTPException(status_code=403, detail="Forbidden: cannot edit whiteboard in another workspace")

    board.elements_json = payload.elements_json
    board.last_modified_by = current_user.email
    board.save()

    return {"status": "saved", "board_pk": board.pk, "version": board.version}
